def build_the_equation(terms: pd.DataFrame) -> pd.DataFrame:
    terms = terms.sort_values(by='power', ascending=False)
    parts = []
    for _, row in terms.iterrows():
        p = int(row['power'])
        f = int(row['factor'])
        sign = '+' if f > 0 else '-'
        coeff = abs(f)
        if p == 0:
            term_str = f"{sign}{coeff}"
        elif p == 1:
            term_str = f"{sign}{coeff}X"
        else:
            term_str = f"{sign}{coeff}X^{p}"
        parts.append(term_str)

    equation = "".join(parts) + "=0"
    return pd.DataFrame([{'equation': equation}])

