def tree_node(tree: pd.DataFrame) -> pd.DataFrame:
    parents = set(tree['p_id'].dropna().unique())
    def classify(row):
        if pd.isna(row['p_id']):
            return 'Root'
        elif row['id'] in parents:
            return 'Inner'
        else:
            return 'Leaf'
    tree['type'] = tree.apply(classify, axis=1)
    return tree[['id', 'type']]

